import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BlT4x7ys.js";const p=JSON.parse('{"title":"The server database is the catalog, and nothing ships bundled","description":"","frontmatter":{"status":"accepted","date":"2026-11-15T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0033-the-server-database-is-the-catalog-and-nothing-ships-bundled.md","filePath":"docs/adr/0033-the-server-database-is-the-catalog-and-nothing-ships-bundled.md"}'),n={name:"docs/adr/0033-the-server-database-is-the-catalog-and-nothing-ships-bundled.md"};function i(r,e,d,h,l,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="the-server-database-is-the-catalog-and-nothing-ships-bundled" tabindex="-1">The server database is the catalog, and nothing ships bundled <a class="header-anchor" href="#the-server-database-is-the-catalog-and-nothing-ships-bundled" aria-label="Permalink to &quot;The server database is the catalog, and nothing ships bundled&quot;">​</a></h1><p>Supersedes the bundled catalog of <a href="./0008-curated-catalog-with-stable-slugs">ADR 0008</a>, <a href="./0015-catalog-text-lives-in-translation-files">ADR 0015</a>, <a href="./0026-the-server-holds-the-catalog-as-a-draft-and-published-versions">ADR 0026</a> and <a href="./0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a> (<a href="https://github.com/tkint/coach-poulpy/issues/451" target="_blank" rel="noreferrer">#451</a>).</p><p>Until now the apps shipped a copy of the catalog (<code>catalog/data/exercises.json</code> plus the <code>catalog</code> translation files, merged and embedded at build time), the server filled its database from it on first start, and a phone seeded its own database from it. Since the admin (<a href="https://github.com/tkint/coach-poulpy/issues/439" target="_blank" rel="noreferrer">#439</a>) edits and publishes exercises, the files were a second source that nothing edited by hand and every release had to carry. The maintainer decided the database is the only source.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><ul><li><strong>The server database holds the catalog.</strong> The admin creates, edits, publishes and retires exercises there. A fresh database starts with no exercises; nothing seeds it.</li><li><strong>Phones start with no exercises</strong> and download them, as before, from <code>GET /api/v1/catalog/exercises</code> (ADR 0030). A phone that has never downloaded the catalog, such as a first launch with no connection, shows no exercises until its first download. An empty state for that case is left to a later issue.</li><li><strong>Phones that already hold exercises keep them.</strong> Nothing removes what is in a phone&#39;s database.</li><li><strong>The server&#39;s workout views read exercise names from the database</strong>, the latest published revision of each exercise, not from a bundled catalog.</li><li><strong>The <code>catalog</code> translation namespace and its merge tool are gone</strong>: exercise text is stored in each exercise as a map from language to string, as the server and phones already hold it. Fink&#39;s catalog translations are made in the admin, not in pull requests.</li><li><strong>Tests use <code>Catalog.sample</code>-like fixtures in code</strong>: the <code>catalog-sample</code> module holds a frozen copy of the exercises as they were, and only test source sets depend on it.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A release no longer carries catalog changes; a catalog fix reaches phones as soon as it is published.</li><li>There is no catalog in the repository to review as a diff. The admin&#39;s publish review and the database are the record.</li><li>The catalog is only as safe as the database backup; <a href="./../deploying-the-server">the server deployment</a> is where that is kept.</li><li>A development database starts empty and needs exercises created in the admin, or a copy of a real database.</li></ul>',7)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
